\u003d\u0024\u0040\u0072\u004c\u0037\u0060\u0022\u0037\u0061\u0056\u0030\u0026\u004c\u007b\u002e\u0020\u005e\u0045\u0050\u0029\u0048\u0035\u0061\u003f\u0075\u005c\u005b\u0052\u0026\u006f\u007c\u0049\u0040\u006b\u0040\u003b\u0066\u0043\u0030\u0063\u0077\u0047\u0047\u0072\u0066\u006e\u0024\u006d\u0062\u0040\u0031\u0022\u0041\u0029\u0020\u005c\u0027\u003f\u005c\u0076\u0020\u004b\u0033\u0062\u005c\u0023\u0045\u0078\u003e\u0051\u0062\u0064\u0076\u005c\u005e\u0050\u007e\u0068\u002a\u0021\u0040\u0049\u0047\u0075\u0044\u0026\u0027\u005f\u003b\u0072\u003a\u006f\u005e\u0079\u0020\u0048\u0051\u0026\u0051\u0079\u0078\u0059\u0078\u006c\u002e\u0058\u0032\u004e\u002d\u0039\u0077\u0020\u0027\u0039\u004c\u0043\u005c\u0078\u0045\u0074\u0024\u0052\u0074\u0037\u0063\u006b\u005c\u007d\u0055\u007a\u0066\u002b\u0026\u003b\u0045\u0020\u0077\u0072\u0047\u0046\u005e\u0043\u002f\u005b\u004e\u006e\u003a\u0030\u0057\u0073\u0034\u002f\u0067\u0027\u0028\u004e\u0064\u007e\u003b\u004b\u0024\u0067\u0072\u0031\u003f\u0035\u006c\u0031\u0021\u0059\u0035\u0078\u0030\u003f\u004f\u0024\u007b\u0020\u002a\u0074\u0055\u0067\u0069\u0052\u004f\u003e\u0042\u004d\u0026\u0057\u007b\u0074\u0065\u003c\u0027\u0028\u005e\u002a\u0041\u0059\u005c\u0078\u0052\u004c\u0043\u0034\u0073\u0048\u005a\u0054\u0074\u004c\u0077\u006f\u0070\u002c\u006c\u0058\u0066\u0038\u0057\u005a\u006d\u004c\u0031\u005a\u003d\u0066\u0055\u002a\u004f\u0058\u0061\u0056\u0057\u0044\u0059\u0023\u0054\u007b\u0070\u0052\u004e\u0075\u0024\u0057\u0063\u002b\u0062\u004f\u0036\u0044\u0059\u0061\u005f\u0023\u0056\u002c\u003c\u0025\u0032\u0053\u0050\u0022\u0056\u005f\u0034\u005d\u0058\u006d\u0077\u0053\u0063\u005a\u0049\u003f\u0067\u006e\u0023\u0027\u0061\u007c\u002e\u0039\u005b\u007a\u0071\u0032\u0064\u0031\u0024\u0047\u006e\u0062\u006b\u0056\u002b\u0043\u002f\u0079\u0051\u005e\u0069\u004f\u0072\u0025\u004d\u0025\u0077\u005e\u0032\u007d\u0076\u003c\u003c\u0062\u003c\u0076\u0026\u005d\u0021\u004e\u0025\u0047\u007b\u004e\u0074\u0031\u0064\u002d\u0030\u0054\u0038\u005f\u0057\u006d\u006b\u002b\u0045\u0077\u0068\u0048\u007a\u0073\u0063\u0062\u0051\u0077\u0075\u0066\u0042\u0059\u0032\u0066\u004f\u0030\u0052\u002e\u005a\u0038\u0051\u0062\u0059\u0041\u004a\u0062\u0068\u0028\u0060\u0030\u005d\u003b\u0074\u0024\u0073\u0037\u004a\u003b\u003a\u0027\u004c\u004e\u0046\u006a\u004d\u0032\u0040\u0079\u0054\u005c\u0040\u0048\u0056\u0044\u0055\u0059\u003b\u0071\u005d\u0069\u0072\u003f\u0052\u0020\u0045\u0051\u0073\u0039\u006c\u004e\u0060\u0056\u002b\u0069\u0069\u003b\u005a\u0056\u0036\u003c\u003a\u005e\u003d\u004a\u006f\u0025\u0077\u0023\u0048\u0029\u0064\u006e\u0040\u0034\u0061\u0032\u002e\u0068\u002f\u0057\u0041\u004d\u004b\u007d\u002a\u0040\u0069\u0063\u0042\u0059\u0072\u007e\u004a\u0068\u0020\u0079\u0053\u0058\u0041\u002c\u004f\u007e\u007d\u006c\u0029\u0042\u0078\u005f\u0047\u005e\u004c\u0067\u005c\u006d\u0070\u0025\u007b\u004f\u004b\u0027\u0037\u002e\u006e\u004b\u007a\u005f\u0047\u002c\u0042\u0033\u004a\u007c\u0042\u0050\u002f\u0052\u0020\u0060\u0040\u0020\u005e\u0039\u006d\u006f\u0021\u0058\u0041\u0037\u002f\u0036\u0055\u002f\u0027\u007e\u006a\u0073\u0071\u0069\u0029\u0057\u0070\u0026\u003d\u0059\u002a\u006c\u007d\u002a\u0058\u0037\u0059\u003c\u007e\u0026\u0027\u006b\u0058\u0020\u006d\u0039\u0071\u003e\u0077\u002e\u0064\u0060\u0044\u0052\u003e\u007e\u0028\u0056\u003c\u0042\u0021\u005a\u0061\u0064\u0052\u006c\u0068\u007a\u0077\u0035\u004a\u006a\u003c\u0049\u0022\u006e\u0033\u0051\u0043\u003c\u0030\u005e\u0067\u002d\u007c\u0035\u003c\u0050\u0067\u0024\u0062\u0066\u0041\u0032\u003a\u0036\u005f\u0060\u0066\u003a\u0064\u0031\u002e\u0053\u0079\u0042\u0065\u0047\u0045\u0039\u0075\u0050\u0049\u0042\u0072\u0031\u0024\u0040\u002b\u003a\u0077\u006e\u0049\u0075\u006a\u0053\u0055\u0071\u002a\u0060\u0063\u002d\u0045\u0076\u003d\u006d\u007b\u0036\u0034\u0035\u0048\u0073\u007b\u0038\u0029\u0056\u0034\u003e\u0061\u005c\u003b\u0048\u006c\u0044\u0067\u0067\u0026\u0059\u0065\u0065\u0042\u0052\u007d\u005f\u0038\u0034\u0072\u0028\u0053\u0075\u0052\u004c\u0021\u0049\u0039\u0047\u0032\u0036\u0024\u006a\u004a\u0074\u0061\u0044\u0035\u004b\u0029\u0022\u002d\u003f\u0030\u0036\u002a\u0060\u0061\u004f\u007c\u0040\u004d\u007c\u002d\u0063\u006c\u006c\u005a\u004a\u0065\u0065\u002f\u003e\u0064\u0055\u0045\u006f\u0021\u0078\u003a\u0033\u003a\u0026\u0067\u0072\u0046\u003a\u003f\u002f\u0075\u0032\u0023\u0079\u0049\u007b\u0079\u0075\u0030\u0057\u0057\u0078\u0023\u002a\u0030\u007e\u0054\u0045\u0029\u004b\u003a\u002e\u0020\u006d\u0073\u0063\u006a\u0039\u0037\u0025\u0033\u0071\u002f\u0062\u0063\u003d\u0037\u0049\u004b\u006f\u005f\u0077\u0078\u0056\u0020\u006b\u006f\u0070\u003d\u0058\u0067\u0058\u007d\u0074\u0074\u0035\u005d\u0043\u006c\u0033\u0072\u0065\u0044\u0035\u004b\u0039\u0027\u0028\u0032\u007d\u0073\u0020\u0034\u0029\u0066\u0059\u007a\u0030\u0034\u0062\u0033\u0055\u0067\u005c\u004c\u0070\u0062\u0039\u003a\u006f\u006f\u0027\u0041\u006f\u006b\u0036\u0045\u0028\u006a\u0027\u004a\u0062\u007a\u002f\u002b\u002f\u003c\u002e\u0078\u004b\u0034\u0034\u0076\u0027\u0073\u006d\u005d\u0053\u0059\u0074\u0034\u0051\u0044\u0057\u006d\u0025\u0024\u005b\u0036\u0031\u0038\u003e\u0042\u0066\u0069\u0039\u0054\u0068\u0057\u0069\u0021\u003c\u0051\u004c\u0025\u0024\u0044\u003c\u006c\u0071\u007a\u005f\u0060\u0075\u002c\u0055\u002b\u0061\u0020\u0021\u0032\u0020\u007b\u0061\u006f\u0032\u0029\u0045\u0070\u0079\u0057\u003f\u006c\u005a\u0068\u005a\u0063\u0061\u0021\u0055\u0033\u005e\u002c\u0066\u0054\u006d\u004c\u0078\u0075\u0046\u0069\u002a\u007c\u007c\u0067\u006f\u0045\u004c\u0078\u002e\u004c\u0056\u0073\u007e\u0052\u004f\u0042\u0064\u0020\u0057\u0057\u0075\u0062\u0069\u0041\u004a\u0057\u0079\u0030\u003d\u002e\u002b\u006a\u0057\u0074\u005d\u006d\u005f\u0049\u006e\u005f\u0045\u0069\u0050\u005a\u0037\u0068\u0033\u007e\u0070\u0045\u0034\u0060\u0069\u0053\u003a\u004b\u0069\u007a\u007b\u0079\u0065\u0048\u0040\u0020\u0054\u0041\u0070\u007a\u0022\u0073\u005f\u0036\u004d\u0021\u002f\u005f\u005f\u003a\u0026\u0038\u0062\u0050\u0077\u0052\u0044\u0037\u003c\u0069